operation.add:
// Cookie Consent - register extension paths for template and language
$this->template->addPath('extension/cookieconsent', DIR_EXTENSION . 'cookieconsent/catalog/view/template/');
$this->language->addPath('extension/cookieconsent', DIR_EXTENSION . 'cookieconsent/catalog/language/');
$this->load->language('extension/cookieconsent/common/cookie_consent');
$cookie_data['cookie_consent_text'] = $this->language->get('cookie_consent_text');
$cookie_data['cookie_consent_got_it'] = $this->language->get('cookie_consent_got_it');
$cookie_data['cookie_consent_read_more'] = $this->language->get('cookie_consent_read_more');
$this->document->addStyle('extension/cookieconsent/catalog/view/javascript/cookieconsent/scripts/css/cookie_consent.min.css');
$this->document->addScript('extension/cookieconsent/catalog/view/javascript/cookieconsent/scripts/js/cookie_consent.min.js', 'header');
array_push($data['modules'], $this->load->view('extension/cookieconsent/common/cookie_consent', $cookie_data));
